fireSpear:
function fireSpear(ang, mul, kind = 'spear', ox, oy) {
  const s = G.s, p = G.p, { d, crit } = spearDmg(mul), spd = kind === 'q' ? 1600 : s.spearSpd;
  const x = ox ?? p.x, y = oy ?? p.y;
  G.spears.push({ x, y, px: x, py: y, vx: Math.cos(ang) * spd, vy: Math.sin(ang) * spd, ang, dmg: kind === 'q' ? s.qDmg * (crit ? 1.8 : 1) * (s.dmg / 18) ** .6 : d, crit,
    pierce: kind === 'q' ? 99 : s.pierce + (G.feverT > 0 ? 1 : 0), hit: [], life: kind === 'q' ? 760 / spd : (s.range + 160) / spd, kind, carry: 0 });
}

attackThrow:
function attackThrow() {
  const p = G.p, s = G.s, t = p.target && !p.target.dead ? p.target : nearestEnemy(p.x, p.y, s.range + 60);
  if (!t) return;
  const ang = Math.atan2(t.y - p.y, t.x - p.x); p.face = ang;
  fireSpear(ang, 1); p.extraHop = !!G.forms.double;
  for (let i = 1; i <= s.multi; i++) { const off = .2 * Math.ceil(i / 2) * (i % 2 ? 1 : -1); fireSpear(ang + off, .6); }
  p.shots++;
  if (s.storm && p.shots % 8 === 0) { for (let i = 0; i < 8; i++) fireSpear(ang + i * TAU / 8, .6); burst(p.x, p.y, COL.spear, 14, 260, .4); }
  G.parts.push({ ring: true, x: p.x + Math.cos(ang) * 30, y: p.y + Math.sin(ang) * 30, r: 10, life: .12, max: .12, c: '#e9fff8' });
  sfx('throw');
}

startHop:
function startHop(dx, dy) {
  const p = G.p, s = G.s; const l = hyp(dx, dy) || 1; dx /= l; dy /= l;
  // Hop after each throw: dashing toward the target is shorter, sideways is the baseline, backwards is ~25% longer.
  const tx = Math.cos(p.face), ty = Math.sin(p.face), dot = dx * tx + dy * ty;
  const f = dot >= 0 ? 1 - .4 * dot : 1 + .25 * -dot;
  const dist = s.hopDist * f * (p.chillT > 0 ? .8 : 1) * (G.feverT > 0 ? 1.15 : 1);
  let hd = dist; p.hookE = null; p.boltHit = [];
  if (G.forms.hook) { let best = null, bd = 0; for (const e of G.enemies) { if (e.dead || e.dying) continue; const ex = e.x - p.x, ey = e.y - p.y, el = hyp(ex, ey); if (el > 380 + e.r || el < 30) continue; const dot = (ex * dx + ey * dy) / el; if (dot > .82 && dot / el > bd) { bd = dot / el; best = e; } }
    if (best) { hd = Math.max(dist, hyp(best.x - p.x, best.y - p.y) - best.r - 4); const l2 = hyp(best.x - p.x, best.y - p.y) || 1; dx = (best.x - p.x) / l2; dy = (best.y - p.y) / l2; p.hookE = best; G.parts.push({ ring: true, x: best.x, y: best.y, r: best.r + 10, life: .2, max: .2, c: '#bfe8ff' }); } }
  p.wb = 0; p.hvx = dx * hd / s.hopTime; p.hvy = dy * hd / s.hopTime; p.state = 'hop'; p.t = s.hopTime; p.buf = false;
  if (G.phase === 'fight' && G.time - p.lastPerfect > .8 && threatened()) perfectHop();
  p.rStacks = G.time - p.lastHop < 1.6 ? Math.min(5, p.rStacks + 1) : 1; p.lastHop = G.time; G.hops++; if (s.dance) p.danceT = .8; if (G.hops >= 500) unlock('hop500');
  for (let i = 0; i < s.shadow; i++) {
    const e = i === 0 ? nearestEnemy(p.x, p.y, s.range + 100) : nearestEnemy(p.x, p.y, s.range + 100, nearestEnemy(p.x, p.y, s.range + 100));
    if (e) fireSpear(Math.atan2(e.y - p.y, e.x - p.x), .7);
  }
  if (s.foxfire) G.fires.push({ x: p.x, y: p.y, t: .55, n: s.foxfire + (s.groveFire ? 1 : 0) });
  burst(p.x, p.y, COL.mist, 6, 120, .35, 2); sfx('hop');
}

endHop:
function endHop() {
  const p = G.p, s = G.s; p.state = 'idle'; p.land = .12;
  p.lastLand = G.time;
  if (s.nightStep) for (let k = 0; k < s.nightStep; k++) { fireSpear(k * TAU / s.nightStep + rand(0, 1), .5, 'spear', p.x, p.y); G.spears[G.spears.length - 1].gen = 1; }
  if (s.rime) for (const e of G.enemies) if (!e.dead && hyp(e.x - p.x, e.y - p.y) < 120 + e.r) chillHit(e, s.rime);
  if (p.hookE) { const e = p.hookE; p.hookE = null; if (!e.dead && !e.dying && hyp(e.x - p.x, e.y - p.y) < e.r + 60) { e.stacks += 2; e.stackT = 4; dmgEnemy(e, s.dmg * 1.8, false, 'launch', 'kanca'); starBoom(e.x, e.y, 40); sfx('hit', e.x); G.shake = Math.max(G.shake, 6); if (!e.boss) { e.kx += p.hvx * .25; e.ky += p.hvy * .25; } } }
  if (s.postIframe) p.iT = Math.max(p.iT, s.postIframe);
  if (s.flow) p.atkCd *= Math.pow(.7, s.flow);
  if (s.groveFire) G.fires.push({ x: p.x, y: p.y, t: .4, n: s.foxfire + 1 });
  if (s.echo && G.hops % s.echo === 0) { G.echoes.push({ x: p.x, y: p.y, t: .35, R: 110 + s.echoR }); G.parts.push({ ring: true, x: p.x, y: p.y, r: 30, life: .35, max: .35, c: '#bfe8ff' }); }
  if (s.shock) {
    const R = 80 + 20 * s.shock + s.shockR;
    for (const e of G.enemies) {
      if (e.dead) continue; const dx = e.x - p.x, dy = e.y - p.y, d = hyp(dx, dy);
      if (d < R + e.r) { dmgEnemy(e, s.dmg * .45 * s.shock, false, 'launch', 'sok'); if (!e.boss) { e.kx += dx / (d || 1) * 380; e.ky += dy / (d || 1) * 380; } }
    }
    G.parts.push({ ring: true, x: p.x, y: p.y, r: R, life: .25, max: .25, c: COL.mist });
  }
}

castRend:
function castRend() {
  if (!G || G.phase !== 'fight' || paused) return;
  const p = G.p, s = G.s; if (p.rendCd > 0) return;
  let any = false, killed = 0;
  for (const e of G.enemies) {
    if (e.dead || e.dying || e.stacks <= 0 || hyp(e.x - p.x, e.y - p.y) > 1000) continue;
    any = true; const st = e.stacks; const amt = rendDmg(e);
    for (let i = 0; i < Math.min(st, 10); i++) { const a = rand(0, TAU); G.parts.push({ x: e.x, y: e.y - e.r, vx: Math.cos(a) * 340, vy: Math.sin(a) * 340, life: .6, max: .6, c: '#c8fff0', s: 2.6, home: true }); }
    e.lastStacks = st; e.stacks = 0; e.slowT = Math.max(e.slowT, 1.2); e.slowAmt = Math.max(e.slowAmt, .5);
    dmgEnemy(e, amt, false, 'rend');
    if (!e.dead && s.exec && !e.boss && e.hp < e.maxHp * s.exec) { txt(e.x, e.y - 20, 'İNFAZ', COL.gold, true); dmgEnemy(e, e.hp + 1, false, 'rend'); }
    if (e.dead) {
      killed++;
      if (s.harvest) heal(s.harvest);
      if (s.nova) { const R = 90 + 15 * s.nova; starBoom(e.x, e.y, 40 + 10 * s.nova); for (const o of G.enemies) if (!o.dead && o !== e && hyp(o.x - e.x, o.y - e.y) < R + o.r) dmgEnemy(o, s.dmg * .9 * s.nova, false, 'nova', 'nova'); }
      if (s.spread) { const give = Math.ceil(st / 2); for (const o of G.enemies) if (!o.dead && o !== e && hyp(o.x - e.x, o.y - e.y) < 200) { o.stacks += give; o.stackT = 4; } }
    }
  }
  if (!any) { txt(p.x, p.y - 30, 'saplı mızrak yok', '#88a29c'); p.rendCd = .3; return; }
  p.rendCd = killed ? .5 : s.rendCd;
  if (killed >= 5) unlock('rend5');
  if (s.loyal && killed) p.rCd = Math.max(0, p.rCd - 3 * killed);
  G.shake = Math.max(G.shake, 7); sfx('rend'); buzz(killed ? 25 : 12); if (killed) G.hitstop = Math.max(G.hitstop, .05);
  G.parts.push({ ring: true, x: p.x, y: p.y, r: 420, life: .4, max: .4, c: '#d8fff4' }); shock(p.x, p.y, 460, .8, .45);
  if (killed >= 3) { G.impactT = .06; G.speedT = .4; twinkleWorld(p.x, p.y - 30, Math.min(W, H) * .32); }
}

rImpact:
function rImpact() {
  const p = G.p, s = G.s; p.state = 'idle'; p.iT = Math.max(p.iT, .3); p.land = .18; G.zp = Math.max(G.zp, .05);
  for (const e of G.enemies) {
    if (e.dead) continue; const dx = e.x - p.x, dy = e.y - p.y, d = hyp(dx, dy);
    if (d < s.rR + e.r) { e.stacks += 2; e.stackT = 4; e.stunT = e.boss ? s.rStun * .4 : s.rStun; dmgEnemy(e, s.dmg * 2.5, false, 'launch', 'kader');
      if (!e.boss) { e.kx += dx / (d || 1) * 420; e.ky += dy / (d || 1) * 420; } }
  }
  G.parts.push({ ring: true, x: p.x, y: p.y, r: s.rR, life: .35, max: .35, c: COL.gold }); burst(p.x, p.y, COL.gold, 24, 320, .5);
  G.shake = Math.max(G.shake, 12); G.hitstop = Math.max(G.hitstop, .05); buzz(30); sfx('boom'); shock(p.x, p.y, 300, 1.3, .55);
  if (s.starfall) { for (let i = 0; i < 10; i++) fireSpear(i * TAU / 10 + rand(-.1, .1), .8, 'spear', p.x, p.y); twinkleWorld(p.x, p.y - 30, Math.min(W, H) * .22); }
  if (s.aegis) { p.wardT = 0; p.iT = Math.max(p.iT, 1); }
  if (s.rRend) { p.rendCd = 0; castRend(); }
}

dmgEnemy:
function dmgEnemy(e, amt, crit, src, stat) {
  if (e.dead || e.dying || e.reform > 0) return;
  if (e.shield > 0) { const ab = Math.min(e.shield, amt); e.shield -= ab; amt -= ab; if (amt <= 0) { e.flash = .05; txt(e.x, e.y - e.r - 6, Math.round(ab), COL.q); return; } }
  { const k = stat || src || 'spear'; G.dmgBy = G.dmgBy || {}; G.dmgBy[k] = (G.dmgBy[k] || 0) + Math.min(amt, Math.max(0, e.hp)); }
  if (e.frozenT > 0) amt *= 1.3;
  e.hp -= amt; e.flash = .09; e.hitT = .12;
  txt(e.x, e.y - e.r - 6, Math.round(amt) + (crit ? '!' : ''), src === 'rend' ? COL.gold : crit ? '#ffd27a' : COL.spear, crit || src === 'rend');
  if (e.hp <= 0) killEnemy(e, src, crit);
}

killEnemy:
function killEnemy(e, src, crit) {
  if (!e.dying && !e.form2) addFervor(e.boss ? 30 : e.elite ? 14 : 8);
  if (!e.dying && !e.form2 && G.s.ember && e.burnT > 0 && !e._boom) { e._boom = true; starBoom(e.x, e.y, 34); for (const o of G.enemies) if (!o.dead && !o._boom && o !== e && o.hp > 0 && hyp(o.x - e.x, o.y - e.y) < 120 + o.r) { ignite(o); dmgEnemy(o, G.s.dmg * .8, false, 'launch', 'kor'); } }
  if (!e.dying && !e.form2 && G.s.iceShards && e.frozenT > 0 && !e._shard && (e._shard = true)) for (let k = 0; k < G.s.iceShards; k++) { fireSpear(k * TAU / G.s.iceShards, .6, 'spear', e.x, e.y); G.spears[G.spears.length - 1].gen = 1; }
  if (e.runner && G.obj && !G.obj.done) { G.obj.done = G.obj.caught = true; G.shards += 12; heal(G.s.maxHp * .15); addFervor(40); banner('Yakalandı!'); twinkleWorld(e.x, e.y, Math.min(W, H) * .4); }
  if (e.type === 'sporer' && !e.dead) spores(e.x, e.y, 100, 3.4, e.dmg * .4);
  if (e.boss && !e.dying && !e.form2 && G.room >= 10 && e.kind !== 'moon') {
    e.form2 = true; e.hp = 1; e.reform = 1.4; e.stacks = 0; G.eshots.length = 0; G.rings.length = 0; G.erupts.length = 0; G.hazards.length = 0;
    flashScreen(.5); slowmo(.6, .35); G.shake = 16; G.speedT = .8; sfx('bigboom'); banner('İkinci form'); twinkleWorld(e.x, e.y - e.r, Math.min(W, H) * .6);
    return;
  }
  if (e.boss && !e.dying) {
    // Metal Slug style boss death: freeze in place, chain of explosions, then the final blast
    e.dying = 1.8; e.hp = 0; e.stacks = 0; G.kills++; G.shards += 30;
    G.enemies.forEach(o => { if (!o.dead && o !== e) { o.dead = true; shatter(o, false); } });
    G.eshots.length = 0; G.spawns.length = 0; G.hazards.length = 0; G.rings.length = 0; G.erupts.length = 0; G.waveIdx = G.waves.length;
    slowmo(1.4, .3); flashScreen(.6); G.shake = 22; G.speedT = 1.8; buzz([60, 40, 60]); sfx('bigboom');
    return;
  }
  e.dead = true; G.kills++; G.combo++; G.comboT = 2.5; if (G.combo >= 50) unlock('combo50');
  if (G.s.boneBurst && Math.max(e.stacks, e.lastStacks || 0) >= 5) { for (let i = 0; i < 6; i++) fireSpear(i * TAU / 6 + rand(0, .5), .6, 'spear', e.x, e.y); G.parts.push({ ring: true, x: e.x, y: e.y, r: 60, life: .25, max: .25, c: '#ffd8a8' }); }
  const sh = (e.elite ? 3 * (G.mod.eliteShards || 1) : e.type === 'brute' ? 2 : 1) * (G.mod.shards || 1); G.shards += sh;
  if (e.type === 'bomb' && !e.blew) bombBlast(e, false);
  if (e.type === 'chest') {
    if (e.mimic) { const m = makeEnemyFull('mimic', e.x, e.y, false); m.cd = 1; G.enemies.push(m); banner('Mimik!'); G.shake = 12; sfx('scream'); }
    else { dropOrbs(e, 5); G.shards += 12; twinkleWorld(e.x, e.y, Math.min(W, H) * .4); G.chestOpened = true; }
  }
  if (e.type === 'mimic') { dropOrbs(e, 5); G.shards += 20; G.chestOpened = true; unlock('mimic'); }
  if (e.elite === 'burst') { for (let i = 0; i < 8; i++) eshot(e.x, e.y, i * TAU / 8 + .2, 190, e.dmg * .6, 8); }
  G.lastKill = { x: e.x, y: e.y }; dropOrbs(e, sh);
  if (PRAISE[G.combo]) praise(G.combo);
  const launch = e.type !== 'wisp' && (src === 'launch' || src === 'q' || (src === 'rend' && (e.lastStacks || 0) >= 5) || (crit && Math.random() < .35) || (e.elite && Math.random() < .5));
  shatter(e, !!e.elite || e.type === 'brute');
  if (launch) popFlare(e);
}

hurt:
function hurt(d, src) {
  const p = G.p; if (G.phase !== 'fight' || invuln()) return;
  if (G.god) { txt(p.x, p.y - 30, '-' + Math.round(d), '#88a29c'); return; }
  if (G.s.ward && p.wardT <= 0) { p.wardT = G.s.ward; p.iT = .5; txt(p.x, p.y - 30, 'KALKAN', '#bfe8ff', true); G.parts.push({ ring: true, x: p.x, y: p.y, r: 46, life: .3, max: .3, c: '#bfe8ff' }); sfx('ding'); buzz(15); return; }
  buzz(40);
  G.lastHit = src || 'Bilinmeyen'; G.takenBy = G.takenBy || {}; G.takenBy[G.lastHit] = (G.takenBy[G.lastHit] || 0) + d;
  d *= 1 + .2 * vowLv('pain');
  G.fervor = Math.max(0, G.fervor - 35); if (G.feverT > 0) G.feverT = Math.max(0, G.feverT - 2);
  p.hp -= d; p.iT = .6; G.hurtA = 1; G.roomDmg = (G.roomDmg || 0) + d; G.shake = Math.max(G.shake, 10); sfx('hurt'); txt(p.x, p.y - 30, '-' + Math.round(d), COL.blood, true);
  burst(p.x, p.y, COL.blood, 10, 180, .4);
  if (p.hp <= 0) { p.hp = 0; gameOver(); }
}

perfectHop:
function perfectHop() {
  const p = G.p, tw = !!G.forms.time; p.lastPerfect = G.time; p.iT = Math.max(p.iT, tw ? .8 : .45); slowmo(tw ? 1.1 : .4, tw ? .2 : .3); if (tw) addFervor(15); G.zp = Math.max(G.zp, .05);
  txt(p.x, p.y - 34, 'MÜKEMMEL', '#ffe39a', true); G.parts.push({ ring: true, x: p.x, y: p.y, r: 70, life: .3, max: .3, c: '#ffe39a' }); sfx('perfect'); buzz(25);
  for (let i = G.eshots.length - 1; i >= 0; i--) { const b = G.eshots[i]; if (hyp(b.x - p.x, b.y - p.y) < 140 && !b.orb) { burst(b.x, b.y, '#ffe39a', 4, 140, .25, 2); G.eshots.splice(i, 1); } }
  for (let k = 0; k < 3; k++) { const e = k === 0 ? nearestEnemy(p.x, p.y, G.s.range + 120) : G.enemies.filter(o => !o.dead && !o.dying)[Math.floor(Math.random() * G.enemies.length)]; if (e) fireSpear(Math.atan2(e.y - p.y, e.x - p.x), 1, 'spear'); }
  addFervor(25); G.perfects = (G.perfects || 0) + 1;
  if (!meta.perfectTip) { meta.perfectTip = 1; store.set('ym_meta', meta); toast('Mükemmel Sekme! Saldırı çarpmadan hemen önce sekmek zamanı büker ve Coşku doldurur.'); }
}

threatened:
function threatened() {
  const p = G.p;
  const W2 = G.forms.time ? 1.5 : 1;
  for (const b of G.eshots) { const dx = p.x - b.x, dy = p.y - b.y, d = hyp(dx, dy), v = hyp(b.vx, b.vy) || 1; if (d < 95 * W2 && (dx * b.vx + dy * b.vy) / (d * v || 1) > .5 && d / v < .32 * W2) return true; }
  for (const e of G.enemies) { if (e.dead || e.dying) continue; const d = hyp(e.x - p.x, e.y - p.y) - e.r; if (d < 70 && (e.st === 'dash' || e.st === 'dive' || e.st === 'leap' || e.sub === 'dash' || (e.st === 'fuse' && e.t < .3))) return true; }
  for (const u of G.erupts) if (u.t < .35 && hyp(u.x - p.x, u.y - p.y) < u.r + 12) return true;
  for (const r of G.rings) if (Math.abs(hyp(r.x - p.x, r.y - p.y) - r.r) < 45) return true;
  return false;
}

addFervor:
function addFervor(n) {
  if (!G || G.phase !== 'fight') return; G.fervorIdle = 0;
  if (G.feverT > 0) { G.feverT = Math.min(FEVER_T, G.feverT + n * .03); return; }
  G.fervor = Math.min(100, G.fervor + n);
  if (G.fervor >= 100) { G.feverT = FEVER_T; G.fervor = 0; banner('Coşku!'); sfx('fever'); flashScreen(.18); G.zp = Math.max(G.zp, .06); shock(G.p.x, G.p.y, 380, 1, .5); buzz([20, 30, 20]); }
}

patronHit:
function patronHit(sp, e) {
  const s = G.s;
  if (s.ember) ignite(e);
  if (s.frostSpear || (s.crystal && sp.ret)) chillHit(e, 1);
  if (s.chain && (sp.ret && s.starstorm || Math.random() < s.chainP)) chainFrom(e, sp.dmg * .45, s.chainN);
}

chainFrom:
function chainFrom(e, dmg, n) {
  const s = G.s, hit = [e]; let from = e;
  for (let k = 0; k < n; k++) { let best = null, bd = 190; for (const o of G.enemies) { if (o.dead || o.dying || hit.includes(o)) continue; const d = hyp(o.x - from.x, o.y - from.y); if (d < bd) { bd = d; best = o; } }
    if (!best) break; hit.push(best); G.bolts.push({ x0: from.x, y0: from.y - from.r, x1: best.x, y1: best.y - best.r, life: .16 });
    if (s.crystal) chillHit(best, 1); dmgEnemy(best, dmg * (s.crystal && best.frozenT > 0 ? 2 : 1), false, 'launch', 'simsek'); from = best; }
  if (hit.length > 1) sfx('zap', e.x);
}

rollDraft:
function rollDraft() {
  let avail = UPS.filter(u => (G.ups[u.id] || 0) < u.max && (!u.req || u.req(G.ups)) && !(u.id === 'ghost' && G.s.ghostHop)); const out = [];
  // patron cards come from Ata Kapısı; elsewhere only once that patron's core card is owned
  const core = { moon: 'p_moon', ember: 'p_ember', frost: 'p_frost', storm: 'p_storm' };
  if (G.roomType === 'patron') { const pa = avail.filter(u => u.pat === G.roomPatron); if (!G.ups[core[G.roomPatron]] && pa.some(u => u.id === core[G.roomPatron])) out.push(pa.splice(pa.findIndex(u => u.id === core[G.roomPatron]), 1)[0]); while (out.length < 3 && pa.length) out.push(pa.splice(Math.floor(crand() * pa.length), 1)[0]); avail = avail.filter(u => !u.pat && !out.includes(u)); }
  else avail = avail.filter(u => !u.pat || G.ups[core[u.pat]]);
  if (G.roomType === 'altar' || G.roomType === 'chest') { const rare = avail.filter(u => u.r !== 'common'); if (rare.length >= 3) avail = rare; }
  const boost = G.roomType !== 'fight', w = u => boost && u.r === 'common' ? 2 : RW[u.r];
  while (out.length < 3 && avail.length) {
    const tot = avail.reduce((a, u) => a + w(u), 0); let r = crand() * tot, i = 0;
    for (; i < avail.length; i++) { r -= w(avail[i]); if (r <= 0) break; }
    out.push(avail.splice(Math.min(i, avail.length - 1), 1)[0]);
  }
  return out;
}

update:
function update(dt) {
  const p = G.p, s = G.s; G.time += dt; const ox0 = p.x, oy0 = p.y;
