    for (const e of G.enemies) if (!e.dead && hyp(e.x - u.x, e.y - u.y) < u.R + e.r) { e.stacks++; e.stackT = 4; dmgEnemy(e, s.dmg * 1.5, false, 'launch', 'yanki'); } }
