    const t = nearestEnemy(f.x, f.y, 520); if (t) { fireSpear(Math.atan2(t.y - f.y, t.x - f.x), s.groveLord ? 1 : .55, 'spear', f.x, f.y); if (s.groveLord) G.spears[G.spears.length - 1].chill = true; sfx('throw'); }
    if (--f.n > 0 && t) f.t = .18; else G.fires.splice(i, 1); }
  updFervor(dt); updObjective(dt); updPatron(dt); if (G.phase === 'fight') updTutorial(dt);
  if (vowLv('hurry') && G.phase === 'fight' && !G.isBoss) { G.roomT = (G.roomT || 0) + dt; if (G.roomT > 45) { G.hurryT = (G.hurryT || 0) - dt; if (G.hurryT <= 0) { G.hurryT = 2; const a = rand(0, TAU); SHOOTER = null; eshot(Math.cos(a) * ARENA, Math.sin(a) * ARENA, a + Math.PI, 230, 8 + G.room * .4, 9); const b = G.eshots[G.eshots.length - 1]; b.soul = true; b.home = 1.2; b.life = 6; b.src = 'Sabırsız Ay'; } } }
