    if (G.waveIdx >= G.waves.length && alive === 0 && G.spawns.length === 0 && !(G.obj && G.obj.k === 'siege' && G.obj.t > 0)) { G.phase = 'clear'; objCleared(); G.clearT = 1.6; if (G.room >= 5 && !G.isBoss && !G.roomDmg) unlock('nohit'); G.eshots.length = 0; G.rings.length = 0; G.erupts.length = 0;
      if (!G.isBoss && G.lastKill) { twinkleWorld(G.lastKill.x, G.lastKill.y, Math.min(W, H) * .5, .15); slowmo(.7, .25); G.zp = Math.max(G.zp, .08); }
      G.hazards.length = 0; banner('Temizlendi'); G.shards += 2 + Math.floor(G.room / 3) + (G.roomType === 'elite' ? 5 : G.roomType === 'cursed' ? 8 : 0); }
  } else if (G.phase === 'clear') { G.clearT -= dt; if (G.clearT <= 0) { if (G.isBoss) showForms(); else showDraft(); } }
  tickSpawns(dt);

  // player state machine (throw, then hop)
  const wantHop = inp.m > .3;
  switch (p.state) {
    case 'idle': {
      if (p.qQueued && p.qCd <= 0 && G.phase === 'fight') { p.qQueued = false; p.state = 'qcast'; p.t = .22; const e = nearestEnemy(p.x, p.y, 760); p.target = e;
        p.face = e ? Math.atan2(e.y - p.y, e.x - p.x) : inp.m > .2 ? Math.atan2(inp.y, inp.x) : p.face; p.buf = false; break; }
      const tgt = p.atkCd <= 0 && G.phase === 'fight' ? nearestEnemy(p.x, p.y, s.range) : null;
      if (tgt) { p.state = 'windup'; p.t = Math.max(.07, .3 / (s.as * asMul())); p.target = tgt; p.buf = false; p.face = Math.atan2(tgt.y - p.y, tgt.x - p.x); }
      else if (G.forms.double && p.extraHop && inp.m > .5 && G.time - (p.lastLand || -9) < .45 && G.phase === 'fight') { p.extraHop = false; startHop(inp.x, inp.y); p.ghosts.push({ x: p.x, y: p.y, life: .4 }); }
      else if (inp.m > .12) { const sp = s.walk * inp.m * (p.chillT > 0 ? .6 : 1) * (G.feverT > 0 ? 1.25 : 1); p.x += inp.x * sp * dt; p.y += inp.y * sp * dt; p.face = Math.atan2(inp.y, inp.x); }
      break;
