    case 'windup': case 'qcast': {
      p.t -= dt; if (wantHop) { p.buf = true; p.bx = inp.x; p.by = inp.y; }
      if (p.target && !p.target.dead) p.face = Math.atan2(p.target.y - p.y, p.target.x - p.x);
      if (p.t <= 0) {
        if (p.state === 'windup') { attackThrow(); p.atkCd = 1 / (s.as * asMul()); }
        else { fireSpear(p.face, 1, 'q'); p.qCd = Math.max(1.5, s.qCd); sfx('q'); G.shake = Math.max(G.shake, 4); }
        if (p.buf) startHop(p.bx, p.by); else { p.state = 'post'; p.t = .13; }
      }
