    }
    case 'post': p.t -= dt; if (wantHop) startHop(inp.x, inp.y); else if (p.t <= 0) p.state = 'idle'; break;
    case 'rise': {
      p.t -= dt; if (inp.m > .3) { p.buf = true; p.bx = inp.x; p.by = inp.y; }
      if (p.t <= 0) {
        let dx, dy, dist = 420; const e = nearestEnemy(p.x, p.y, 700);
        if (p.buf) { dx = p.bx; dy = p.by; } else if (e) { dx = e.x - p.x; dy = e.y - p.y; dist = clamp(hyp(dx, dy), 120, 420); } else { dx = Math.cos(p.face); dy = Math.sin(p.face); }
        const l = hyp(dx, dy) || 1; p.hvx = dx / l * dist / .3; p.hvy = dy / l * dist / .3; p.face = Math.atan2(dy, dx); p.state = 'fling'; p.t = .3; p.buf = false;
      }
      break;
    }
    case 'fling': G.speedT = Math.max(G.speedT, .15); p.t -= dt; p.x += p.hvx * dt; p.y += p.hvy * dt; p.ghosts.push({ x: p.x, y: p.y, life: .35 }); if (p.t <= 0) rImpact(); break;
    case 'hop': {
      p.t -= dt; p.x += p.hvx * dt; p.y += p.hvy * dt;
      if (s.cinder && (p.cinAcc = (p.cinAcc || 0) + dt) > .035) { p.cinAcc = 0; G.cinders.push({ x: p.x, y: p.y, life: 1 + s.cinder }); }
      if (G.forms.bolt) for (const e of G.enemies) if (!e.dead && !e.dying && !p.boltHit.includes(e) && hyp(e.x - p.x, e.y - p.y) < e.r + 18) { p.boltHit.push(e); e.stacks++; e.stackT = 4; dmgEnemy(e, s.dmg * .9, false, 'launch', 'yildirim'); burst(e.x, e.y, '#bfe8ff', 6, 220, .25, 2); sfx('hit', e.x); }
      if (G.forms.wall && p.wb < 2) { let nx = 0, ny = 0; const pl2 = hyp(p.x, p.y);
        if (pl2 > ARENA - 22) { nx = -p.x / pl2; ny = -p.y / pl2; } else if (G.lay && G.lay.P) for (const c of G.lay.P) { const d2 = hyp(p.x - c.x, p.y - c.y); if (d2 < c.r + 14) { nx = (p.x - c.x) / d2; ny = (p.y - c.y) / d2; } }
        const vn = p.hvx * nx + p.hvy * ny;
        if ((nx || ny) && vn < 0) { p.wb++; p.hvx = (p.hvx - 2 * vn * nx) * 1.15; p.hvy = (p.hvy - 2 * vn * ny) * 1.15; p.t = Math.max(p.t, s.hopTime * .7); p.extraHop = !!G.forms.double;
          G.parts.push({ ring: true, x: p.x, y: p.y, r: 80, life: .25, max: .25, c: '#bfe8ff' }); shock(p.x, p.y, 200, .7, .35); sfx('boom', p.x); G.shake = Math.max(G.shake, 5); addFervor(5);
          for (const e of G.enemies) if (!e.dead && hyp(e.x - p.x, e.y - p.y) < 90 + e.r) { e.stacks++; e.stackT = 4; dmgEnemy(e, s.dmg * 1.2, false, 'launch', 'duvar'); } } }
      p.ghosts.push({ x: p.x, y: p.y, life: .25 });
      if (s.trail) { p.trailAcc += dt; if (p.trailAcc > .025) { p.trailAcc = 0; G.trails.push({ x: p.x, y: p.y, life: .7 + .2 * s.trail }); } }
      if (p.t <= 0) endHop();
      break;
    }
  }
  const pl = hyp(p.x, p.y); if (pl > ARENA - 16) { p.x *= (ARENA - 16) / pl; p.y *= (ARENA - 16) / pl; }
  if (G.lay || G.obj) {
    pushOut(p, 12);
    const air = p.state === 'hop' || p.state === 'fling' || p.state === 'rise';
    if (!air && inVoid(p.x, p.y)) {
      // walking stops at the edge; landing in the void drops you back where you last stood
