      else { p.x = p.safeX ?? 0; p.y = p.safeY ?? 0; if (p.iT <= 0) { hurt(4 + G.room * .25, 'Uçurum'); } p.iT = Math.max(p.iT, .6); burst(p.x, p.y, COL.mist, 12, 200, .4); }
    } else if (!air) { p.safeX = p.x; p.safeY = p.y; }
  }
