  while (p.spCd.length < s.spirits) p.spCd.push(rand(.3, 1));
  for (let i = 0; i < s.spirits; i++) {
    p.spCd[i] -= dt; if (p.spCd[i] > 0 || G.phase !== 'fight') continue;
    const a = p.spA + i * TAU / s.spirits, sx = p.x + Math.cos(a) * 46, sy = p.y + Math.sin(a) * 46;
    const e = nearestEnemy(sx, sy, s.range); if (!e) continue;
    const sa = Math.atan2(e.y - sy, e.x - sx); fireSpear(sa, s.chorus ? .8 : .5, 'spirit', sx, sy); if (s.chorus) fireSpear(sa + .14, .8, 'spirit', sx, sy); p.spCd[i] = 1.3 * s.spiritRate;
  }

