    const g = G.rings[i]; g.r += g.spd * dt;
    if (!g.hit && Math.abs(hyp(p.x - g.x, p.y - g.y) - g.r) < g.w + 8 && pz(p) < 6 && !invuln()) { g.hit = true; hurt(g.dmg, 'Çığlık dalgası'); }
    if (g.r > 1900) G.rings.splice(i, 1);
