    const u = G.erupts[i]; u.t -= dt;
    if (u.t <= 0) { const rc = u.root ? '#b8e070' : u.trap ? '#ffd27a' : '#ff4a5a'; if (hyp(p.x - u.x, p.y - u.y) < u.r + 8) hurt(u.dmg, u.root ? 'Kök' : u.trap ? 'Tuzak' : 'Kan fışkırması'); G.parts.push({ ring: true, x: u.x, y: u.y, r: u.r, life: .3, max: .3, c: rc }); burst(u.x, u.y, rc, 12, 260, .45, 3); if (u.root) sfx('root', u.x); for (let k = 0; k < 4; k++) puff(u.x, u.y - 10, 'd', 12, { vy: rand(-90, -40), vx: rand(-30, 30), a: .5 }); G.shake = Math.max(G.shake, 5); G.erupts.splice(i, 1); }
  }
  // boss hazards
  for (let i = G.hazards.length - 1; i >= 0; i--) { const z = G.hazards[i]; z.life -= dt; if (z.life <= 0) { G.hazards.splice(i, 1); continue; } if (z.life < z.max - .25 && hyp(z.x - p.x, z.y - p.y) < z.r + 9) hurt(z.dmg, z.src || 'Gölge Atlı izi'); }
  // trails
  for (let i = G.trails.length - 1; i >= 0; i--) { const t = G.trails[i]; t.life -= dt; if (t.life <= 0) G.trails.splice(i, 1); }
  if (s.trail && G.trails.length) for (const e of G.enemies) {
    if (e.dead) continue; e.trailCd -= dt; if (e.trailCd > 0) continue;
    for (const t of G.trails) if (hyp(t.x - e.x, t.y - e.y) < e.r + 16) { dmgEnemy(e, s.dmg * .3 * s.trail * s.trailMul, false, undefined, 'iz'); e.trailCd = .3; break; }
  }

  // player spears
  for (let i = G.spears.length - 1; i >= 0; i--) {
    const sp = G.spears[i]; sp.px = sp.x; sp.py = sp.y; sp.x += sp.vx * dt; sp.y += sp.vy * dt; sp.life -= dt;
    if (sp.ret) { // Ay Mızrağı: the spear homes back to the fox
      const dx = p.x - sp.x, dy = p.y - sp.y, d = hyp(dx, dy) || 1, v = hyp(sp.vx, sp.vy); sp.vx = dx / d * v; sp.vy = dy / d * v; sp.life = 1;
      if (d < 26) { if (G.s.eclipse) { starBoom(p.x, p.y, 34); for (const e of G.enemies) if (!e.dead && hyp(e.x - p.x, e.y - p.y) < 100 + e.r) { ignite(e); dmgEnemy(e, G.s.dmg * .6, false, 'launch', 'tutulma'); } } G.spears.splice(i, 1); continue; } }
    else if (G.s.moonSpear && sp.kind === 'spear' && !sp.gen && (sp.life <= 0 || hyp(sp.x, sp.y) > ARENA + 20)) { sp.ret = true; sp.hit = []; sp.dmg *= G.s.retMul; sp.pierce = 99; sp.life = 1; sfx('ret', sp.x); }
    let remove = sp.life <= 0 || hyp(sp.x, sp.y) > ARENA + 40;
    if (!remove) for (const e of G.enemies) {
      if (e.dead || e.dying || sp.hit.includes(e)) continue;
      if (segDist(sp.px, sp.py, sp.x, sp.y, e.x, e.y) > e.r + (sp.kind === 'q' ? 10 : 4)) continue;
      sp.hit.push(e);
      if (sp.kind === 'q') {
        const carry = sp.carry; e.stacks += 2 + carry; e.stackT = 4; sp.carry = 0;
        dmgEnemy(e, sp.dmg, sp.crit, 'q'); G.hitstars.push({ x: sp.x, y: sp.y - 16, life: .1, s: 26, crit: true });
        if (e.dead) { sp.carry = e.stacks; burst(e.x, e.y, COL.q, 10, 240, .4); }
        else { remove = true; break; }
      } else {
        if (e.type === 'knight' && !(e.stunT > 0)) {
          const da = Math.abs(((Math.atan2(sp.y - e.y, sp.x - e.x) - e.ang + Math.PI * 3) % TAU) - Math.PI);
          if (da < 1.15) { burst(sp.x, sp.y, '#cfd8ff', 6, 200, .25, 2); sfx('hit', sp.x); txt(e.x, e.y - e.r - 10, 'BLOK', '#b9c9ff'); G.hitstars.push({ x: sp.x, y: sp.y - 16, life: .1, s: 12, crit: false }); remove = true; break; }
        }
        e.stacks += Math.random() < G.s.heavy ? 2 : 1; e.stackT = 4;
        if (G.s.slow) { e.slowT = 1; e.slowAmt = Math.max(e.slowAmt, G.s.slow); }
        if (sp.chill) { e.slowT = Math.max(e.slowT, 1); e.slowAmt = Math.max(e.slowAmt, .35); }
        const dm = sp.dmg * (G.s.mark && e.stacks >= 3 ? 1 + G.s.mark : 1); if (sp.kind !== 'spirit') addFervor(.8);
        dmgEnemy(e, dm, sp.crit, undefined, sp.kind === 'spirit' ? 'spirit' : 'spear');
        // Seken Işık: a light spear glances off toward the nearest other enemy
        if (G.s.bounce && (sp.gen || 0) < G.s.bounceGen && Math.random() < G.s.bounce) { const o = nearestEnemy(sp.x, sp.y, 320, e); if (o) { fireSpear(Math.atan2(o.y - sp.y, o.x - sp.x), .6, 'spear', sp.x, sp.y); const b = G.spears[G.spears.length - 1]; b.gen = (sp.gen || 0) + 1; b.hit.push(e); G.parts.push({ ring: true, x: sp.x, y: sp.y, r: 14, life: .15, max: .15, c: '#e9fff8' }); } }
        if (G.s.leech) heal(sp.dmg * G.s.leech);
        if (sp.kind !== 'q') patronHit(sp, e);
        if (!e.boss) { e.kx += sp.vx * .05; e.ky += sp.vy * .05; }
        burst(sp.x, sp.y, COL.spear, 3, 120, .2, 2); sfx('hit', sp.x); G.hitstars.push({ x: sp.x, y: sp.y - 16, life: .1, s: sp.crit ? 24 : 13, crit: sp.crit });
        if (sp.pierce-- <= 0) { if (G.s.moonSpear && sp.kind === 'spear' && !sp.gen && !sp.ret) { sp.ret = true; sp.hit = [e]; sp.dmg *= G.s.retMul; sp.pierce = 99; sfx('ret', sp.x); break; } remove = true; break; }
      }
    }
    if (!remove && G.lay && G.lay.P && G.lay.P.some(c => hyp(sp.x - c.x, sp.y - c.y) < c.r)) { remove = true; burst(sp.x, sp.y, COL.spear, 4, 140, .2, 2); }
    if (remove) G.spears.splice(i, 1);
  }

  // enemies
  for (const e of G.enemies) if (!e.dead) updEnemy(e, dt);
  // separation
  const es = G.enemies;
  for (let i = 0; i < es.length; i++) { const a = es[i]; if (a.dead) continue;
    for (let j = i + 1; j < es.length; j++) { const b = es[j]; if (b.dead) continue;
      const dx = b.x - a.x, dy = b.y - a.y, d = hyp(dx, dy), m = a.r + b.r;
      if (d < m && d > .01) { const push = (m - d) / 2, nx = dx / d, ny = dy / d; a.x -= nx * push; a.y -= ny * push; b.x += nx * push; b.y += ny * push; } } }
  for (let i = es.length - 1; i >= 0; i--) if (es[i].dead) es.splice(i, 1);

