    const b = G.eshots[i];
    if (b.orb) { b.oa += b.ow * dt; b.orad += b.ovr * dt; b.x = b.orb.x + Math.cos(b.oa) * b.orad; b.y = b.orb.y + Math.sin(b.oa) * b.orad; }
    if (b.home) { const cur = Math.atan2(b.vy, b.vx), da = ((Math.atan2(p.y - b.y, p.x - b.x) - cur + Math.PI * 3) % TAU) - Math.PI, tr = clamp(da, -b.home * dt, b.home * dt), v = hyp(b.vx, b.vy); b.vx = Math.cos(cur + tr) * v; b.vy = Math.sin(cur + tr) * v; }
    b.x += b.vx * dt; b.y += b.vy * dt; b.life -= dt;
    if (hyp(b.x - p.x, b.y - p.y) < b.r + 11 && !invuln()) { hurt(b.dmg, b.src || (b.soul ? 'Ruh mermisi' : b.blood ? 'Kan bıçağı' : 'Muhafız mermisi')); if (b.ice) p.chillT = 1.6; G.eshots.splice(i, 1); continue; }
    if (b.life <= 0 || hyp(b.x, b.y) > ARENA + 30 || (G.lay && G.lay.P && !b.orb && G.lay.P.some(c => hyp(b.x - c.x, b.y - c.y) < c.r))) G.eshots.splice(i, 1);
  }
