    if (!q.ring) { q.x += q.vx * dt; q.y += q.vy * dt; if (!q.home) { q.vx *= .92; q.vy *= .92; } } if (q.life <= 0) G.parts.splice(i, 1); }
  for (let i = G.texts.length - 1; i >= 0; i--) { const t = G.texts[i]; t.life -= dt; t.y -= 40 * dt; if (t.life <= 0) G.texts.splice(i, 1); }

  const lx = p.x + Math.cos(p.face) * 40, ly = p.y - 18 + Math.sin(p.face) * 40;
  G.cam.x += (lx - G.cam.x) * Math.min(1, dt * 6); G.cam.y += (ly - G.cam.y) * Math.min(1, dt * 6); G.zp *= Math.exp(-7 * dt);
}

updEnemy:
function updEnemy(e, dt) {
  SHOOTER = e;
  if (e.reform > 0) {
